CREATE TABLE resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),church_id uuid NOT NULL REFERENCES churches,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('room','vehicle','equipment')),UNIQUE(church_id,id));
CREATE TABLE church_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),church_id uuid NOT NULL REFERENCES churches,title text NOT NULL,kind text NOT NULL CHECK(kind IN ('meeting','service','event','class')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','cancelled')),created_by uuid NOT NULL REFERENCES users,UNIQUE(church_id,id),CHECK(ends_at>starts_at));
CREATE TABLE resource_bookings(church_id uuid NOT NULL,event_id uuid NOT NULL,resource_id uuid NOT NULL,PRIMARY KEY(event_id,resource_id),FOREIGN KEY(church_id,event_id) REFERENCES church_events(church_id,id),FOREIGN KEY(church_id,resource_id) REFERENCES resources(church_id,id));
CREATE FUNCTION prevent_resource_overlap() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target church_events; BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.resource_id::text,0));
 SELECT * INTO target FROM church_events WHERE id=NEW.event_id;
 IF target.status='scheduled' AND EXISTS(SELECT 1 FROM resource_bookings b JOIN church_events e ON e.id=b.event_id WHERE b.resource_id=NEW.resource_id AND e.status='scheduled' AND e.starts_at<target.ends_at AND e.ends_at>target.starts_at) THEN RAISE EXCEPTION 'Resource booking conflict'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION prevent_resource_overlap() FROM PUBLIC;
CREATE TRIGGER resource_conflict BEFORE INSERT ON resource_bookings FOR EACH ROW EXECUTE FUNCTION prevent_resource_overlap();
CREATE TABLE ministry_teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),church_id uuid NOT NULL REFERENCES churches,name text NOT NULL,UNIQUE(church_id,id));
CREATE TABLE ministry_members(church_id uuid NOT NULL,team_id uuid NOT NULL,user_id uuid NOT NULL,role text NOT NULL,PRIMARY KEY(team_id,user_id),FOREIGN KEY(church_id,team_id) REFERENCES ministry_teams(church_id,id),FOREIGN KEY(user_id,church_id) REFERENCES memberships(user_id,church_id));
ALTER TABLE schedules ADD COLUMN ends_at timestamptz;
UPDATE schedules SET ends_at=starts_at+interval '2 hours';
ALTER TABLE schedules ALTER COLUMN ends_at SET NOT NULL;
ALTER TABLE schedules ADD CONSTRAINT schedule_interval CHECK(ends_at>starts_at);
ALTER TABLE schedules ADD COLUMN event_id uuid;
ALTER TABLE schedules ADD COLUMN team_id uuid;
ALTER TABLE schedules ADD CONSTRAINT schedule_event FOREIGN KEY(church_id,event_id) REFERENCES church_events(church_id,id);
ALTER TABLE schedules ADD CONSTRAINT schedule_team FOREIGN KEY(church_id,team_id) REFERENCES ministry_teams(church_id,id);
CREATE TABLE volunteer_unavailability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),church_id uuid NOT NULL,user_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,CHECK(ends_at>starts_at),FOREIGN KEY(user_id,church_id) REFERENCES memberships(user_id,church_id));
CREATE TABLE operational_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),church_id uuid NOT NULL REFERENCES churches,scope text NOT NULL CHECK(scope IN ('people','cells','pastoral','finance')),encrypted_title text NOT NULL,person_id uuid,assigned_to uuid,created_by uuid NOT NULL REFERENCES users,due_on date NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done','cancelled')),version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id),FOREIGN KEY(assigned_to,church_id) REFERENCES memberships(user_id,church_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['resources','church_events','resource_bookings','ministry_teams','ministry_members'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY operation_read ON %I FOR SELECT USING(church_id=tenant_id() AND (local_role() IS NOT NULL OR can_access(''cells'')))',t);
 EXECUTE format('GRANT SELECT ON %I TO ecclesia_app',t); EXECUTE format('GRANT ALL ON %I TO ecclesia_service',t);
END LOOP; END $$;
ALTER TABLE volunteer_unavailability ENABLE ROW LEVEL SECURITY; ALTER TABLE volunteer_unavailability FORCE ROW LEVEL SECURITY;
CREATE POLICY availability_read ON volunteer_unavailability FOR SELECT USING(church_id=tenant_id() AND (user_id=actor_id() OR can_access('cells',true)));
GRANT SELECT ON volunteer_unavailability TO ecclesia_app;GRANT ALL ON volunteer_unavailability TO ecclesia_service;
ALTER TABLE operational_tasks ENABLE ROW LEVEL SECURITY; ALTER TABLE operational_tasks FORCE ROW LEVEL SECURITY;
CREATE POLICY task_read ON operational_tasks FOR SELECT USING(church_id=tenant_id() AND can_access(scope) AND (scope<>'pastoral' OR created_by=actor_id() OR assigned_to=actor_id()));
GRANT SELECT ON operational_tasks TO ecclesia_app;GRANT ALL ON operational_tasks TO ecclesia_service;
CREATE INDEX events_start ON church_events(church_id,starts_at);
CREATE INDEX bookings_resource ON resource_bookings(resource_id);
CREATE INDEX tasks_due ON operational_tasks(church_id,scope,status,due_on);
REVOKE INSERT,UPDATE ON schedules FROM ecclesia_app;
GRANT UPDATE(response) ON schedules TO ecclesia_app;
